// Works out which Amazon product to price, from an API call or a watchlist row.
// Accepts an ASIN (B0BXYCS74H), an Amazon product URL, or a product name to search for.
const item = $input.item.json;
const fromApi = item.headers !== undefined && (item.body !== undefined || item.query !== undefined);
const req = fromApi ? { ...(item.query ?? {}), ...(typeof item.body === 'object' ? item.body : {}) } : item;

// "$1,299.99", "1.299,99 €" and 1299.99 all become 1299.99
const parsePrice = (value) => {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  let s = String(value ?? '').match(/\d[\d.,]*/)?.[0] ?? '';
  if (!s) return null;
  const lastComma = s.lastIndexOf(',');
  const lastDot = s.lastIndexOf('.');
  if (lastComma > lastDot) {
    s = /,\d{1,2}$/.test(s) ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
    s = s.replace(/\./g, '');
  } else {
    s = s.replace(/,/g, '');
  }
  const n = parseFloat(s);
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
};

const raw = String(req.asin ?? req.url ?? req.product ?? req.query ?? '').trim();
let marketplace = String(req.marketplace ?? '').trim().toLowerCase()
  .replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '') || 'amazon.com';

const base = {
  source: fromApi ? 'api' : 'sheet',
  input: raw,
  row_number: item.row_number ?? 0,
  target_price: parsePrice(req.target_price),
  previous_price: fromApi ? null : parsePrice(item.last_price),
  lowest_price: fromApi ? null : parsePrice(item.lowest_price),
};

const fail = (code, error) => ({ json: { ...base, marketplace, lookup: 'error', ok: false, code, error } });

if (!raw) {
  return fail('invalid_request', 'No product given. Send an ASIN (like B0BXYCS74H), an Amazon product URL, or a product name.');
}

const ASIN_IN_URL = /\/(?:dp|gp\/product|gp\/aw\/d|product)\/([A-Z0-9]{10})(?=[/?#]|$)/i;
const link = raw.match(/https?:\/\/\S+/i)?.[0].replace(/[).,!?]+$/, '');

if (link) {
  // (URL() isn't available in n8n's Code node, so read the host with a pattern)
  const host = (link.match(/^https?:\/\/([^/?#:\s]+)/i)?.[1] ?? '').toLowerCase().replace(/^www\./, '');
  const isAmazon = /^(smile\.)?amazon\.[a-z.]+$/.test(host);
  const isShortLink = /^(amzn\.(to|eu|asia)|a\.co)$/.test(host);
  if (!isAmazon && !isShortLink) {
    return fail('invalid_request', `Only Amazon links are supported, but this link is on ${host || 'an unknown site'}.`);
  }
  if (isAmazon) marketplace = host.replace(/^smile\./, '');
  const asin = link.match(ASIN_IN_URL)?.[1]?.toUpperCase() ?? '';
  return {
    json: {
      ...base,
      marketplace,
      asin,
      // A clean /dp/ URL avoids tracking parameters; short links are passed on for Pumice to follow
      amazonUrl: asin ? `https://www.${marketplace}/dp/${asin}` : link,
      lookup: 'url',
    },
  };
}

// ASINs are 10 letters and digits with at least one digit
if (/^(?=.*\d)[A-Z0-9]{10}$/i.test(raw)) {
  const asin = raw.toUpperCase();
  return { json: { ...base, marketplace, asin, amazonUrl: `https://www.${marketplace}/dp/${asin}`, lookup: 'url' } };
}

return { json: { ...base, marketplace, asin: '', amazonUrl: '', searchQuery: raw, lookup: 'search' } };

// Picks the first Amazon product page from Pumice Universal Search results,
// preferring the requested marketplace (amazon.com by default).
const request = $('Read Product Request').item.json;
const res = $input.item.json;

// The response shape can vary, so check the common containers
let list = res.results ?? res.data ?? res.items ?? res.pages ?? res.urls ?? res.organic ?? [];
if (list && !Array.isArray(list) && Array.isArray(list.results)) list = list.results;
if (!Array.isArray(list)) list = [];

const ASIN_IN_URL = /\/(?:dp|gp\/product|gp\/aw\/d)\/([A-Z0-9]{10})(?=[/?#]|$)/i;
const pages = list
  .map((r) => (typeof r === 'string' ? r : (r.url || r.link || r.source_url || r.page_url || '')))
  .map((url) => {
    // (URL() isn't available in n8n's Code node, so read the host with a pattern)
    const host = (String(url).match(/^https?:\/\/([^/?#:\s]+)/i)?.[1] ?? '').toLowerCase().replace(/^www\./, '');
    const asin = String(url).match(ASIN_IN_URL)?.[1]?.toUpperCase();
    return /^amazon\.[a-z.]+$/.test(host) && asin ? { host, asin } : null;
  })
  .filter(Boolean);

const page = pages.find((p) => p.host === request.marketplace) ?? pages[0];

if (!page) {
  const reason = typeof res.error === 'string' ? res.error : res.error?.message;
  return {
    json: {
      ...request,
      ok: false,
      code: reason ? 'scrape_failed' : 'not_found',
      error: reason
        ? `Pumice Universal Search failed (${reason}). Try again in a few minutes.`
        : `Couldn't find "${request.searchQuery}" on Amazon. Try the ASIN or the Amazon product URL instead.`,
    },
  };
}

return {
  json: {
    ...request,
    marketplace: page.host,
    asin: page.asin,
    amazonUrl: `https://www.${page.host}/dp/${page.asin}`,
  },
};

