// Turns Pumice Smart Scrape's output into a clean price record, and compares it
// with the watchlist's previous and lowest prices to decide whether to send an alert.
const request = $('Amazon Page Ready').item.json;
const res = $input.item.json;

const fail = (code, error, extra = {}) => ({ json: { ...request, ...extra, ok: false, code, error } });

if (res.error && res.data === undefined && res.result === undefined) {
  const reason = typeof res.error === 'string' ? res.error : res.error?.message;
  return fail('scrape_failed', `Pumice Smart Scrape failed${reason ? ` (${reason})` : ''}. Try again in a few minutes.`);
}

// The extracted fields can arrive at the top level or nested, as an object or a JSON string
let d = res.data ?? res.result ?? res.output ?? res.extracted ?? res;
if (typeof d === 'string') {
  try { d = JSON.parse(d); } catch (e) { d = {}; }
}
if (Array.isArray(d)) d = d[0] ?? {};
if (d && typeof d === 'object' && d.price === undefined && d.product && typeof d.product === 'object') d = d.product;
d = d ?? {};

const pick = (...keys) => keys.map((k) => d[k]).find((v) => v !== undefined && v !== null && v !== '');

// "$1,299.99", "1.299,99 €" and 1299.99 all become 1299.99
const parsePrice = (value) => {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  let s = String(value ?? '').match(/\d[\d.,]*/)?.[0] ?? '';
  if (!s) return null;
  const lastComma = s.lastIndexOf(',');
  const lastDot = s.lastIndexOf('.');
  if (lastComma > lastDot) {
    s = /,\d{1,2}$/.test(s) ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (/^\d{1,3}(\.\d{3})+$/.test(s)) {
    s = s.replace(/\./g, '');
  } else {
    s = s.replace(/,/g, '');
  }
  const n = parseFloat(s);
  return Number.isFinite(n) ? Math.round(n * 100) / 100 : null;
};
const parseNumber = (value) => {
  const n = parseFloat(String(value ?? '').replace(/,/g, '').match(/\d+(\.\d+)?/)?.[0] ?? '');
  return Number.isFinite(n) ? n : null;
};

const CURRENCY_BY_MARKETPLACE = {
  'amazon.com': 'USD', 'amazon.ca': 'CAD', 'amazon.com.mx': 'MXN', 'amazon.com.br': 'BRL',
  'amazon.co.uk': 'GBP', 'amazon.de': 'EUR', 'amazon.fr': 'EUR', 'amazon.it': 'EUR', 'amazon.es': 'EUR',
  'amazon.nl': 'EUR', 'amazon.com.be': 'EUR', 'amazon.ie': 'EUR', 'amazon.se': 'SEK', 'amazon.pl': 'PLN',
  'amazon.com.tr': 'TRY', 'amazon.ae': 'AED', 'amazon.sa': 'SAR', 'amazon.eg': 'EGP', 'amazon.in': 'INR',
  'amazon.co.jp': 'JPY', 'amazon.sg': 'SGD', 'amazon.com.au': 'AUD',
};

const rawPrice = pick('price', 'current_price', 'buy_box_price', 'sale_price', 'deal_price');
const price = parsePrice(rawPrice);
const title = String(pick('title', 'product_title', 'name') ?? '').trim();
const availability = String(pick('availability', 'availability_text', 'stock') ?? '').trim();

if (price === null) {
  return fail(
    'no_price',
    'Pumice read the Amazon page but found no price. The product may be unavailable, or have no Buy Box price.',
    { title, availability },
  );
}

const scrapedCurrency = String(pick('currency', 'currency_code') ?? '').trim().toUpperCase();
const currency = /^[A-Z]{3}$/.test(scrapedCurrency)
  ? scrapedCurrency
  : (CURRENCY_BY_MARKETPLACE[request.marketplace] ?? 'USD');

const listPrice = parsePrice(pick('list_price', 'was_price', 'typical_price', 'original_price'));
const inStockField = pick('in_stock', 'is_in_stock');
const inStock = typeof inStockField === 'boolean'
  ? inStockField
  : /unavailable|out of stock|no disponible|nicht verfügbar/i.test(availability) ? false
  : /in stock|only \d+ left|available|auf lager|en stock|disponible/i.test(availability) ? true
  : null;

const scrapedAsin = String(pick('asin') ?? '').trim().toUpperCase();
const asin = /^[A-Z0-9]{10}$/.test(scrapedAsin) ? scrapedAsin : request.asin;

const money = (n) => {
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(n);
  } catch (e) {
    return `${currency} ${n.toFixed(2)}`;
  }
};

// Watchlist comparisons. An alert fires when the price first drops to or below
// the target price, or when it drops below the lowest price seen so far.
const target = request.target_price;
const previous = request.previous_price;
const lowestBefore = request.lowest_price;
const reachedTarget = target !== null && price <= target && !(previous !== null && previous <= target);
const newLow = lowestBefore !== null && price < lowestBefore;
const alerts = [];
if (reachedTarget) alerts.push(`At or below your target price of ${money(target)}`);
if (newLow) alerts.push(`Lowest price so far (previous low ${money(lowestBefore)})`);

return {
  json: {
    ...request,
    ok: true,
    asin,
    title,
    url: asin ? `https://www.${request.marketplace}/dp/${asin}` : request.amazonUrl,
    price,
    price_display: money(price),
    currency,
    list_price: listPrice,
    discount_percent: listPrice && listPrice > price ? Math.round((1 - price / listPrice) * 100) : null,
    in_stock: inStock,
    availability,
    seller: String(pick('seller', 'buy_box_seller', 'sold_by', 'merchant') ?? '').trim(),
    rating: parseNumber(pick('rating', 'stars', 'average_rating')),
    review_count: parseNumber(pick('review_count', 'reviews', 'ratings_count', 'rating_count')),
    image_url: String([pick('image_url', 'main_image', 'image', 'image_urls', 'images')].flat()[0] ?? ''),
    target_display: target !== null ? money(target) : '',
    previous_display: previous !== null ? money(previous) : '',
    lowest_display: money(lowestBefore !== null ? Math.min(lowestBefore, price) : price),
    below_target: target !== null ? price <= target : null,
    price_change: previous !== null ? Math.round((price - previous) * 100) / 100 : null,
    lowest_price: lowestBefore !== null ? Math.min(lowestBefore, price) : price,
    alert: alerts.join('; '),
    checked_at: new Date().toISOString(),
  },
};

// Shapes the API response and picks the HTTP status code
const r = $input.item.json;
const STATUS = { invalid_request: 400, not_found: 404, no_price: 422, scrape_failed: 502 };

if (!r.ok) {
  return { json: { status: STATUS[r.code] ?? 500, body: { ok: false, code: r.code, error: r.error, input: r.input } } };
}

const body = {
  ok: true,
  asin: r.asin,
  title: r.title,
  url: r.url,
  price: r.price,
  currency: r.currency,
  list_price: r.list_price,
  discount_percent: r.discount_percent,
  in_stock: r.in_stock,
  availability: r.availability,
  seller: r.seller,
  rating: r.rating,
  review_count: r.review_count,
  image_url: r.image_url,
  checked_at: r.checked_at,
};
if (r.target_price !== null) {
  body.target_price = r.target_price;
  body.below_target = r.below_target;
}

return { json: { status: 200, body } };
